python3 << 'EOF'
import requests
from datetime import datetime, timedelta
import json

HA_URL = "http://localhost:8123"
HA_TOKEN = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiIxZmY0NDhiYTQxMzE0MzBiYjA1MTcyYzJjMWM0MjliMiIsImlhdCI6MTc3MjU0ODc3NywiZXhwIjoyMDg3OTA4Nzc3fQ.13dEu7WP_kwr1nIwlsZhcU3jlBCm3QYiO27UyNnIE28"

headers = {"Authorization": f"Bearer {HA_TOKEN}", "Content-Type": "application/json"}

# 现在时间是 2026-03-03，先获取完整数据
# 先获取每个entities的完整历史

entities = [
    "counter.la_ba_ba",
    "counter.he_shui", 
    "counter.zao_fang_ci_wo",
    "counter.zao_fang_zhu_wo",
    "sensor.beep_temperature",
    "sensor.beep_humidity",
]

all_data = {}

for entity in entities:
    url = f"{HA_URL}/api/history/period/2026-02-24T00:00:00+00:00"
    params = {"filter_entity_id": entity, "end_time": "2026-03-03T23:59:59+00:00"}

    resp = requests.get(url, headers=headers, params=params)
    if resp.status_code == 200 and resp.json():
        all_data[entity] = resp.json()[0]
    else:
        print(f"Error fetching {entity}: {resp.status_code}")

# 分析每日数据
# 由于计数器每日0点重置，我们需要找出每天的开始值和结束值来计算活动次数

results = {
    "拉粑粑": {},
    "喝水": {},
    "次卧访问": {},
    "主卧访问": {},
    "温度": {},
    "湿度": {}
}

# 处理计数器数据 - 需要按天分析
for counter_name, entity_id in [("拉粑粑", "counter.la_ba_ba"), ("喝水", "counter.he_shui"), ("次卧访问", "counter.zao_fang_ci_wo"), ("主卧访问", "counter.zao_fang_zhu_wo")]:
    if entity_id not in all_data:
        continue

    history = all_data[entity_id]
    # 按日期分组统计
    daily_counts = {}

    # 由于计数器会每天重置，我们需要分析每次变化
    for i, item in enumerate(history):
        dt = datetime.fromisoformat(item['last_changed'].replace('+00:00', ''))
        date = dt.date()
        state = int(float(item['state']))

        if date not in daily_counts:
            daily_counts[date] = {"start": state, "end": state, "changes": 0}

        if i > 0:
            prev_state = int(float(history[i-1]['state']))
            # 如果当前值小于前一个值，说明是重置（跨天）
            if state < prev_state:
                daily_counts[date]["end"] = state
            else:
                daily_counts[date]["end"] = state
                daily_counts[date]["changes"] += 1

    for date, info in sorted(daily_counts.items()):
        # 活动次数 = 变化次数
        results[counter_name][str(date)] = info["changes"]

# 处理温湿度数据 - 计算每日平均值
for sensor_name, entity_id in [("温度", "sensor.beep_temperature"), ("湿度", "sensor.beep_humidity")]:
    if entity_id not in all_data:
        continue

    history = all_data[entity_id]
    daily_values = {}

    for item in history:
        dt = datetime.fromisoformat(item['last_changed'].replace('+00:00', ''))
        date = dt.date()
        try:
            value = float(item['state'])
            if date not in daily_values:
                daily_values[date] = []
            daily_values[date].append(value)
        except:
            pass

    for date, values in sorted(daily_values.items()):
        if values:
            results[sensor_name][str(date)] = {
                "avg": round(sum(values)/len(values), 1),
                "max": max(values),
                "min": min(values)
            }

print("=" * 80)
print("最近7天猫咪活动与温湿度数据汇总")
print("=" * 80)

# 打印表格
dates = sorted(set(list(results["拉粑粑"].keys()) + list(results["喝水"].keys()) + list(results["主卧访问"].keys())))[-7:]

print(f"\n{'日期':<12} {'拉粑粑':>6} {'喝水':>6} {'次卧':>6} {'主卧':>6} {'温度(°C)':<18} {'湿度(%)':<18}")
print("-" * 80)

for date in dates:
    la_ba = results["拉粑粑"].get(date, 0)
    he_shui = results["喝水"].get(date, 0)
    ci_wo = results["次卧访问"].get(date, 0)
    zhu_wo = results["主卧访问"].get(date, 0)
    temp = results["温度"].get(date, {})
    humidity = results["湿度"].get(date, {})

    temp_str = f"{temp.get('avg', '-')}" if temp else "-"
    humidity_str = f"{humidity.get('avg', '-')}" if humidity else "-"

    print(f"{date:<12} {la_ba:>6} {he_shui:>6} {ci_wo:>6} {zhu_wo:>6} {temp_str:>18} {humidity_str:>18}")

print("\n" + "=" * 80)
print("详细温度湿度范围")
print("=" * 80)
for date in dates:
    temp = results["温度"].get(date, {})
    humidity = results["湿度"].get(date, {})
    if temp:
        print(f"{date}: 温度 {temp.get('min', '-')}~{temp.get('max', '-')}°C (平均{temp.get('avg', '-')}°C), 湿度 {humidity.get('min', '-')}~{humidity.get('max', '-')}% (平均{humidity.get('avg', '-')}%)")
EOF

