headers = {"Authorization": f"Bearer {HA_TOKEN}"}

# 获取3月4日的温湿度数据
# 先找传感器实体
resp = requests.get(f"{HA_URL}/api/states", headers=headers)
all_states = resp.json()

print("传感器实体:")
sensors = {}
for s in all_states:
    eid = s['entity_id']
    if 'sensor' in eid and ('temperature' in eid.lower() or 'humidity' in eid.lower() or '温' in eid.lower() or '湿' in eid.lower()):
        print(f"  {eid}: {s['state']} {s['attributes'].get('unit_of_measurement','')}")
        sensors[eid] = s

# 查看历史
for eid in sensors:
    url = f"{HA_URL}/api/history/period/2026-03-04?filter_entity_id={eid}"
    req = urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(req) as f:
            data = json.load(f)
            if data and len(data) > 0:
                events = data[0]
                # 取早上8点和晚上20点的值
                values = {}
                for e in events:
                    hour = int(e['last_changed'][11:13])
                    if hour in [8, 20]:
                        values[hour] = e['state']
                print(f"\n{eid}:")
                print(f"  早8点: {values.get(8, 'N/A')}")
                print(f"  晚20点: {values.get(20, 'N/A')}")
    except Exception as ex:
        print(f"Error: {ex}")
